// gen_demo_tokens：demo 主题 token 单源发射器（P0 契约批，2026-10-21，refs #222）。
//
// 真源：demo/tokens.json（W3C DTCG 子集——每个 token = {$value, $type}；
// 顶层 base / themeOrder+themes[colorScheme,tokens] / sizes 三组）。
// 产物：demo/src/tokens.css（入库，@generated 头，禁手改）。
//
// 为什么是「入库 + -check」形态（vitro-generator-contract §两种产物形态）：
// 产物被 app.css `@import` 直接消费、且需要 git 里的单源可审阅——发射形态
// 会让「主题色板改了什么」在 review 里消失，故选入库 + 字节比对。
//
// 契约：
//   - flag 包（-check / -selftest / -src / -out），禁手工扫 os.Args；
//   - 输出确定性：base → themeOrder 逐主题（JSON 数组定序，不依赖 map 序）→
//     sizes 按数值序；块内 token 按变量名排序（同名不重复 ⇒ 语义无关）；
//   - 行尾归一化后再比对（CRLF 假红）；
//   - -check 无副作用：内存生成比对，不写盘、不改产物；
//   - 完备性断言（fail loud）：主题集 = themeOrder 集、colorScheme ∈ {light,dark}、
//     token 名一律 --vr- 前缀、$value 非空、products 首项 = 产物路径、
//     generatedBy 必须是本工具（防真源被别的工具接管而闸空转）；
//   - 未知字段一律拒绝（DisallowUnknownFields）——JSON 里写错的键不允许静默忽略。
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

const (
	genPath   = "scripts/gen_demo_tokens"
	header    = "/* @generated by " + genPath + " —— 禁手改（真源：demo/tokens.json） */"
	schemaURI = "https://design-tokens.github.io/community-group/format/"
)

type token struct {
	Value string `json:"$value"`
	Type  string `json:"$type"`
}

type tokenGroup struct {
	Tokens map[string]token `json:"tokens"`
}

type theme struct {
	ColorScheme string           `json:"colorScheme"`
	Tokens      map[string]token `json:"tokens"`
}

type tokensDoc struct {
	Schema      string                `json:"$schema"`
	Description string                `json:"$description"`
	GeneratedBy string                `json:"generatedBy"`
	Products    []string              `json:"products"`
	Base        tokenGroup            `json:"base"`
	ThemeOrder  []string              `json:"themeOrder"`
	Themes      map[string]theme      `json:"themes"`
	Sizes       map[string]tokenGroup `json:"sizes"`
}

func die(format string, args ...any) {
	fmt.Fprintf(os.Stderr, genPath+": "+format+"\n", args...)
	os.Exit(1)
}

// load：解析 + 完备性断言（任何一条不成立即红——产物宁可不出，不留半套 token）。
func load(path string) *tokensDoc {
	raw, err := os.ReadFile(path)
	if err != nil {
		die("读真源失败 %s: %v", path, err)
	}
	dec := json.NewDecoder(strings.NewReader(strings.ReplaceAll(string(raw), "\r\n", "\n")))
	dec.DisallowUnknownFields()
	var doc tokensDoc
	if err := dec.Decode(&doc); err != nil {
		die("解析 %s 失败: %v", path, err)
	}
	if doc.Schema != schemaURI {
		die("$schema 必须是 %q（当前 %q）", schemaURI, doc.Schema)
	}
	if doc.GeneratedBy != genPath {
		die("generatedBy 必须是 %q（当前 %q）——真源被别的工具接管时本闸必须红", genPath, doc.GeneratedBy)
	}
	if len(doc.Products) == 0 || doc.Products[0] != "demo/src/tokens.css" {
		die("products 首项必须是 demo/src/tokens.css（当前 %v）", doc.Products)
	}
	if len(doc.Base.Tokens) == 0 {
		die("base.tokens 为空")
	}
	if len(doc.ThemeOrder) == 0 {
		die("themeOrder 为空")
	}
	seen := map[string]bool{}
	for _, k := range doc.ThemeOrder {
		if seen[k] {
			die("themeOrder 重复：%s", k)
		}
		seen[k] = true
		if _, ok := doc.Themes[k]; !ok {
			die("themeOrder 列了 %q 但 themes 里没有", k)
		}
	}
	if len(seen) != len(doc.Themes) {
		die("themes 里有 %d 个主题，themeOrder 只列了 %d 个（漏列即输出不确定）", len(doc.Themes), len(seen))
	}
	checkTokens := func(where string, toks map[string]token) {
		if len(toks) == 0 {
			die("%s 没有 token", where)
		}
		for name, t := range toks {
			if !strings.HasPrefix(name, "--vr-") {
				die("%s 的 token 名 %q 不是 --vr- 前缀（消费面只认 CSS 变量）", where, name)
			}
			if strings.TrimSpace(t.Value) == "" {
				die("%s 的 %s 没有 $value", where, name)
			}
			if strings.TrimSpace(t.Type) == "" {
				die("%s 的 %s 没有 $type（DTCG 子集要求显式类型）", where, name)
			}
		}
	}
	checkTokens("base", doc.Base.Tokens)
	for _, k := range doc.ThemeOrder {
		th := doc.Themes[k]
		if th.ColorScheme != "light" && th.ColorScheme != "dark" {
			die("主题 %s 的 colorScheme 必须是 light/dark（当前 %q）", k, th.ColorScheme)
		}
		checkTokens("themes."+k, th.Tokens)
	}
	if len(doc.Sizes) == 0 {
		die("sizes 为空")
	}
	for k, g := range doc.Sizes {
		if _, err := strconv.Atoi(k); err != nil {
			die("sizes 的档位键必须是整数（当前 %q）", k)
		}
		checkTokens("sizes."+k, g.Tokens)
	}
	return &doc
}

func sortedNames(toks map[string]token) []string {
	names := make([]string, 0, len(toks))
	for n := range toks {
		names = append(names, n)
	}
	sort.Strings(names)
	return names
}

func sortedSizes(m map[string]tokenGroup) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool {
		a, _ := strconv.Atoi(keys[i])
		b, _ := strconv.Atoi(keys[j])
		return a < b
	})
	return keys
}

func writeBlock(b *strings.Builder, sel, scheme string, toks map[string]token) {
	fmt.Fprintf(b, "%s {\n", sel)
	if scheme != "" {
		fmt.Fprintf(b, "  color-scheme: %s;\n", scheme)
	}
	for _, n := range sortedNames(toks) {
		fmt.Fprintf(b, "  %s: %s;\n", n, toks[n].Value)
	}
	b.WriteString("}\n")
}

// render：确定性输出（同输入必同字节）。块间空一行，文件以单换行结尾。
func render(doc *tokensDoc) string {
	var b strings.Builder
	b.WriteString(header + "\n")
	b.WriteString("/* 语义：base = 字体/尺寸/动效基座；themes = 五主题色板（color-scheme 随主题）；sizes = 字号档 */\n\n")
	writeBlock(&b, ":root", "", doc.Base.Tokens)
	b.WriteString("\n")
	for _, k := range doc.ThemeOrder {
		th := doc.Themes[k]
		writeBlock(&b, fmt.Sprintf(":root[data-theme=%q]", k), th.ColorScheme, th.Tokens)
		b.WriteString("\n")
	}
	sizes := sortedSizes(doc.Sizes)
	for i, k := range sizes {
		writeBlock(&b, fmt.Sprintf(":root[data-size=%q]", k), "", doc.Sizes[k].Tokens)
		if i < len(sizes)-1 {
			b.WriteString("\n")
		}
	}
	return b.String()
}

// diffHint：第一处差异的行号与两侧内容（-check 红时给人看的定位信息）。
func diffHint(want, got string) string {
	w := strings.Split(want, "\n")
	g := strings.Split(got, "\n")
	for i := 0; i < len(w) && i < len(g); i++ {
		if w[i] != g[i] {
			return fmt.Sprintf("第 %d 行起不一致：\n  期望: %s\n  实际: %s", i+1, w[i], g[i])
		}
	}
	if len(w) != len(g) {
		return fmt.Sprintf("行数不一致：期望 %d 行，实际 %d 行", len(w), len(g))
	}
	return "内容一致（不应走到这里）"
}

// verify 是 -check 的唯一判定点。-selftest 直接调用它（审查 P2-4：旧 selftest
// 只检查 diffHint 里有没有注入串，把 `got != want` 改成恒假仍能绿——自证面
// 与判定面脱节）。统一后 selftest 证明「判定函数对篡改输入必红」。
func verify(out, want, got string) error {
	got = strings.ReplaceAll(got, "\r\n", "\n")
	if got == want {
		return nil
	}
	return fmt.Errorf("%s: 产物漂移 %s ← 真源 demo/tokens.json\n%s", genPath, out, diffHint(want, got))
}

func check(doc *tokensDoc, out string) {
	want := render(doc)
	raw, err := os.ReadFile(out)
	if err != nil {
		die("-check 读产物失败 %s: %v（先跑一次生成）", out, err)
	}
	if err := verify(out, want, string(raw)); err != nil {
		fmt.Fprintln(os.Stderr, err)
		fmt.Fprintf(os.Stderr, "修复：go run ./%s\n", genPath)
		os.Exit(1)
	}
	fmt.Printf("%s: -check 通过（%s ≡ demo/tokens.json）\n", genPath, out)
}

// selftest：J9 埋雷义务的内存形态——同集必须绿、篡改必须红且定位可见。
// 直接走 verify（不是复述 diffHint），判定面空转即自证红。
func selftest(doc *tokensDoc, out string) {
	want := render(doc)
	if err := verify(out, want, want); err != nil {
		die("-selftest 同集应绿，实际红：%v", err)
	}
	tampered := strings.Replace(want, "--vr-fs:", "--vr-fs-TAMPERED:", 1)
	if tampered == want {
		die("-selftest 注入失败：真源里没有 --vr-fs，注入面失效")
	}
	err := verify(out, want, tampered)
	if err == nil {
		die("-selftest 判定空转：篡改后 verify 仍绿（-check 比对面失效）")
	}
	if !strings.Contains(err.Error(), "TAMPERED") {
		die("-selftest 注入未体现在 diffHint（定位面失能）：%v", err)
	}
	fmt.Printf("%s: -selftest 通过（同集绿 + 篡改 --vr-fs → verify 判红且定位可见）\n", genPath)
}

func main() {
	checkFlag := flag.Bool("check", false, "只比对产物与真源（不写盘；漂移即 exit 1）")
	selftestFlag := flag.Bool("selftest", false, "内存注入篡改，证明 -check 比对面会红")
	src := flag.String("src", "demo/tokens.json", "token 真源")
	out := flag.String("out", "demo/src/tokens.css", "产物路径")
	flag.Parse()

	doc := load(*src)
	if *selftestFlag {
		selftest(doc, *out)
		return
	}
	if *checkFlag {
		check(doc, *out)
		return
	}
	if err := os.WriteFile(*out, []byte(render(doc)), 0o644); err != nil {
		die("写产物失败 %s: %v", *out, err)
	}
	fmt.Printf("%s: 已生成 %s（%d 主题 / %d 字号档）\n", genPath, *out, len(doc.ThemeOrder), len(doc.Sizes))
}
